import {openInvoice} from './invoice.js';
import {saveSupplierWithConnection} from './supplier-connection.js';
import {escapeHtml as e,fmt,units,manager,stockOperator,decimal,orderLines,receiptLines,movementChange,friendlyError} from './core.js';
import {db,loadWorkspace,getTransactions,rpcWrite,saveRecord} from './data.js';
import {barChart,donutChart,stockRows} from './charts.js';
import {supplierPages,supplierContent,supplierOrderBody,preferredSupplierAccount,supplierBusinessName} from './supplier.js';
import {supplierDemoSnapshot} from './supplier-demo.js';
import {SITE_URL} from './config.js';
import {demoRestaurant,demoData,demoTransactions} from './demo.js';

const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const pages={home:['Home','home'],ingredients:['Ingredients','leaf'],suppliers:['Suppliers','truck'],orders:['Purchase orders','bag'],receiving:['Receiving','box'],transactions:['Transactions','activity'],workspace:['Workspace','settings']};
const paths={home:'M3 10 12 3l9 7M5 9v11h14V9M9 20v-7h6v7',leaf:'M20 4c-9-1-15 2-15 8a6 6 0 0 0 10 4c4-4 5-8 5-12ZM4 21l11-11',truck:'M2 6h12v12H2zM14 10h4l4 4v4h-8M6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',bag:'M5 7h14l1 14H4L5 7ZM8 7V5a4 4 0 0 1 8 0v2',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7 5l9 4',activity:'M2 12h4l3-8 6 16 3-8h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',down:'M12 4v16M6 14l6 6 6-6',up:'M12 20V4M6 10l6-6 6 6',check:'M5 12l4 4L19 6',close:'M6 6l12 12M18 6 6 18',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',logout:'M9 4H4v16h5M12 12h9M17 8l4 4-4 4',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',phone:'M5 3H2c0 11 8 19 19 19v-5l-5-2-2 3c-4-2-6-4-8-8l3-2-2-5H5Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l3 2',edit:'m4 15 12-12 5 5L9 20l-6 1 1-6Z',menu:'M4 6h16M4 12h16M4 18h16',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 7M19 14a6 6 0 0 1 3 5v2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4ZM8 12l3 3 5-6',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',alert:'M12 3 2 21h20L12 3ZM12 9v5M12 17v1',calendar:'M4 5h16v16H4V5ZM8 2v6M16 2v6M4 10h16'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
let preferredPortal='owner';try{if(localStorage.getItem('gateway-portal')==='supplier')preferredPortal='supplier';}catch{}
let state={portal:preferredPortal,supplierAccounts:[],supplierAccount:null,supplierSnapshot:null,supplierRestaurant:'',chartUnit:'kg',chartCurrency:'USD',session:null,restaurants:[],memberships:[],restaurant:null,role:'viewer',data:null,page:'home',demo:false,loading:false,error:'',transactions:[],transactionCount:0,transactionPage:0,txItem:'',txType:'',search:'',filter:'all',authMode:'login',authNote:'',authError:'',updated:null};
let epoch=0,modalState=null,toastTimer,authIdentity=null,supplierCreating=false;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.restaurant?.currency||'USD',maximumFractionDigits:2}).format(Number(n||0));
function date(value,time=false){if(!value)return 'Not set';const d=new Date(value.length===10?`${value}T12:00:00Z`:value);return Number.isNaN(+d)?'—':new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:time?undefined:'numeric',...(time?{hour:'numeric',minute:'2-digit'}:{}),timeZone:state.restaurant?.timezone||'America/New_York'}).format(d);}
const label=s=>String(s).replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const item=id=>state.data?.inventory_items.find(i=>i.id===id);
const supplier=id=>state.data?.suppliers.find(s=>s.id===id);
const level=id=>state.data?.inventory_levels.find(i=>i.item_id===id);
const canManage=()=>state.portal==='owner'&&!state.demo&&manager(state.role);
const canStock=()=>state.portal==='owner'&&!state.demo&&stockOperator(state.role);
const total=o=>state.data.purchase_order_lines.filter(l=>l.purchase_order_id===o.id).reduce((n,l)=>n+Number(l.quantity_ordered)*Number(l.unit_price),0);
const openOrders=()=>state.data?.purchase_orders.filter(o=>['ordered','partially_received'].includes(o.status))||[];
const statusTag=status=>`<span class="tag ${status==='received'?'good':status==='partially_received'?'warning':status==='cancelled'?'bad':'info'}">${e(label(status))}</span>`;
const action=(name,text,ico='',extra='')=>`<button class="btn" data-action="${name}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const empty=(title,desc,button='')=>`<div class="empty"><div class="empty-icon">${icon('box')}</div><h3>${e(title)}</h3><p>${e(desc)}</p>${button}</div>`;
function toast(message,error=false){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=message;t.className=`toast${error?' error':''}`;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,6500);}
const activePages=()=>state.portal==='supplier'?supplierPages:pages;
function route(){const key=location.hash.replace(/^#\/?/,'').split('?')[0];return activePages()[key]?key:'home';}
function navigate(page){if(location.hash===`#/${page}`){state.page=page;render();}else location.hash=`/${page}`;}
function resetFilters(){state.search='';state.filter='all';}
function brand(){return `<a class="brand" href="#/home"><span class="brand-mark">g.</span><span>gateway<small>INVENTORY</small></span></a>`;}
function landing(){
  const signup=state.authMode==='signup',reset=state.authMode==='reset';
  return `<div class="landing"><header class="landing-nav">${brand()}<div class="row"><span class="muted nav-extra">${state.portal==='supplier'?'Made for stronger restaurant connections.':'Made for the way kitchens work.'}</span><button class="btn small" data-action="demo">Explore sample workspace ${icon('arrow')}</button></div></header><main id="main" class="landing-main"><div class="landing-copy"><span class="eyebrow">A little more clarity. A lot less waste.</span><h1>${state.portal==='supplier'?'Your customers.<br>Your deliveries.':'Your kitchen.<br>Your inventory.'}<br><em>All in view.</em></h1><p>${state.portal==='supplier'?'Stay connected with restaurant customers. Follow their orders and delivery confirmations in one organized workspace.':'From the first order to the last ingredient, bring your purchasing, deliveries, and stock into one organized workspace.'}</p><div class="feature-list">${(state.portal==='supplier'?['Connect with restaurants','Follow customer orders','Track confirmed deliveries']:['Know what’s on hand','Keep deliveries on track','Account for every change']).map(label=>`<span>${icon('check')} ${label}</span>`).join('')}</div><div class="landing-actions"><button class="btn" data-action="demo">Take a look inside ${icon('arrow')}</button></div></div><div class="auth-panel"><span class="eyebrow">${state.portal==='supplier'?'SUPPLIER WORKSPACE':'RESTAURANT WORKSPACE'}</span><h2 style="margin-top:12px">${reset?'Reset your password':signup?state.portal==='supplier'?'Start with your business':'Start with your kitchen':'Welcome back.'}</h2><p>${reset?'We’ll email you a link to choose a new password.':signup?state.portal==='supplier'?'Create an account, then set up your supplier business.':'Create an account, then set up your restaurant.':state.portal==='supplier'?'Sign in to view your restaurant connections and orders.':'Sign in to manage your restaurant’s inventory.'}</p>${state.authNote?`<div class="form-notice" role="status">${e(state.authNote)}</div>`:''}${portalChoices()}<form id="auth-form"><label class="field">Email address<input name="email" type="email" autocomplete="email" placeholder="you@restaurant.com" required></label>${!reset?`<label class="field">Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?'8':'1'}" ${signup?'placeholder="At least 8 characters"':''} required></label>`:''}<div class="form-error" role="alert">${e(state.authError)}</div><button class="btn primary full" type="submit">${reset?'Send reset link':signup?'Create account':'Sign in'} ${icon('arrow')}</button></form><div class="auth-switch">${signup||reset?'Already have an account?':'New to Gateway Inventory?'} <button class="text-button" data-action="auth-mode" data-mode="${signup||reset?'login':'signup'}">${signup||reset?'Sign in':'Create an account'}</button></div>${!signup&&!reset?'<div class="auth-switch"><button class="text-button" data-action="auth-mode" data-mode="reset">Forgot password?</button></div>':''}<div class="auth-divider">OR EXPLORE FIRST</div><button class="btn full" data-action="demo">Open read-only sample workspace</button><p class="auth-foot">Your selected portal opens after sign-in. Data access depends on your verified business memberships.</p></div></main><footer class="landing-bottom"><span>Gateway Solutions · Restaurant operations</span><span>${state.portal==='supplier'?'Restaurants → Orders → Deliveries':'Ingredients → Purchasing → Receiving → Stock'}</span></footer></div>`;
}
function onboarding(){return `<header class="landing-nav">${brand()}<button class="btn small" data-action="logout">Sign out</button></header><main class="onboarding" id="main"><div class="panel"><div class="panel-body"><span class="eyebrow">YOUR FIRST WORKSPACE</span><h1>Let’s meet your restaurant.</h1><p>Create a workspace to start adding ingredients and suppliers. You’ll become its owner.</p><form id="restaurant-form"><label class="field">Restaurant name<input name="name" maxlength="160" placeholder="For example, The Green Table" required></label><div class="form-error" role="alert">${e(state.error)}</div><button type="submit" class="btn primary full">Create restaurant ${icon('arrow')}</button></form><p class="subtle-note">Already part of a team? Ask your project administrator to add your account, then refresh.</p><button class="btn ghost small" data-action="reload-membership">${icon('refresh')} Refresh membership</button></div></div></main>`;}
function shell(content){
 const low=state.data?.inventory_levels.filter(i=>i.is_low_stock).length||0;
 return `<div class="layout"><aside class="sidebar" id="sidebar">${brand()}<div><div class="eyebrow" style="padding:0 14px 12px">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${Object.entries(pages).map(([key,[name,ico]])=>`<a href="#/${key}" class="${key===state.page?'active':''}" ${key===state.page?'aria-current="page"':''}>${icon(ico)}${name}${key==='ingredients'&&low?`<span class="count">${low}</span>`:''}</a>`).join('')}</nav></div><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<h3 style="margin-top:8px">A well-stocked kitchen.</h3><p>Small, consistent updates make the big picture clearer.</p><a class="quiet-link" href="#/transactions">View stock activity →</a></div><div class="side-user"><span class="avatar">${state.demo?'D':e((state.session?.user.email||'U').slice(0,1).toUpperCase())}</span><div class="user-info"><strong>${state.demo?'Sample workspace':e(state.session?.user.email)}</strong><small>${state.demo?'Read-only preview':e(state.role)}</small></div><button class="btn ghost small" data-action="${state.demo?'exit-demo':'logout'}" aria-label="${state.demo?'Exit sample workspace':'Sign out'}">${icon('logout')}</button></div></div></aside><div><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span class="crumb">Workspace <span style="margin:0 9px">/</span><strong>${pages[state.page][0]}</strong></span></div><div class="topbar-right"><button class="btn small portal-switch" data-action="switch-portal">Switch portal</button><span class="status"><span class="dot"></span>${state.demo?'Sample data':'Connected workspace'}</span><select id="restaurant-picker" class="workspace-select" aria-label="Choose restaurant">${(state.demo?[demoRestaurant]:state.restaurants).map(r=>`<option value="${e(r.id)}" ${r.id===state.restaurant?.id?'selected':''}>${e(r.name)}</option>`).join('')}</select><button class="icon-button" data-action="refresh" aria-label="Refresh data" ${state.loading?'disabled':''}>${icon('refresh')}</button></div></header>${state.loading?'<div class="loading-line" role="status" aria-label="Loading current data"></div>':''}<main id="main" class="content">${state.demo?'<div class="demo-banner"><p><strong>Sample workspace</strong> · Fictional data for exploration. Sign in to save changes to your restaurant.</p><button class="btn small" data-action="exit-demo">Sign in</button></div>':''}${state.error?`<div class="error-banner" role="alert"><strong>We couldn’t refresh this workspace.</strong><p>${e(state.error)} ${state.updated?'The data below may be out of date.':''}</p></div>`:''}${content}</main></div></div>`;
}
function heading(title,subtitle,buttons=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${buttons}</div></div>`;}
function home(){
 const d=state.data,active=d.inventory_items.filter(i=>i.is_active),low=d.inventory_levels.filter(i=>i.is_low_stock),orders=openOrders();
 const button=canManage()?'<button class="btn primary" data-action="new-order">'+icon('plus')+' New purchase order</button>':'';
 const metrics=[['Active ingredients',active.length,'Ingredients in your kitchen','leaf'],['Need attention',low.length,'Below their reorder point','alert'],['Open orders',orders.length,'Awaiting a delivery','bag'],['Active suppliers',d.suppliers.filter(s=>s.is_active).length,'Your supply network','truck']];
 return `${heading('Your kitchen, in view.','A clear picture of what’s on hand and what’s coming next.',button)}<div class="hero"><div><span class="eyebrow">EVERY INGREDIENT COUNTS</span><h2>Good service starts<br>with a prepared kitchen.</h2><p>${low.length?`${low.length} ${low.length===1?'ingredient is':'ingredients are'} below their reorder point. A quick stock review keeps your next service on track.`:'Your next great service starts here. Keep orders, deliveries, and everyday stock changes in one place.'}</p></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 180 140"><path d="M24 72h132l-14 57H38z" fill="#c3d0ad"/><path d="M50 73 67 20M73 73l5-47M100 74l29-48M116 75l30-36" stroke="#728b5b" stroke-width="6" stroke-linecap="round"/><ellipse cx="58" cy="44" rx="15" ry="8" fill="#91a878" transform="rotate(30 58 44)"/><ellipse cx="88" cy="42" rx="17" ry="9" fill="#a6bb8c" transform="rotate(-40 88 42)"/><ellipse cx="119" cy="44" rx="16" ry="9" fill="#8ba574" transform="rotate(35 119 44)"/><circle cx="86" cy="77" r="24" fill="#bd9476"/><circle cx="120" cy="85" r="19" fill="#d1ab8a"/><path d="M24 80h132M47 92v22M68 92v22M91 92v22M113 92v22M135 92v22" stroke="#e3e9d6" stroke-width="5" stroke-linecap="round"/><path d="M27 130h125" stroke="#adbda0" stroke-width="3" stroke-linecap="round"/></svg></div></div><div class="stats">${metrics.map(([title,value,note,ico])=>`<div class="stat"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(ico)}</span></div><strong class="number">${value}</strong><small>${note}</small></div>`).join('')}</div>${ownerCharts()}${!active.length?`<div class="panel"><div class="steps"><div class="step"><div class="step-num">01 / INGREDIENTS</div><h3>Build your ingredient list</h3><p>Add the ingredients you use, their base units, and reorder points.</p><a class="btn small" href="#/ingredients">View ingredients ${icon('arrow')}</a></div><div class="step"><div class="step-num">02 / SUPPLIERS</div><h3>Know your suppliers</h3><p>Add contacts, delivery lead times, and pack sizes.</p><a class="btn small" href="#/suppliers">View suppliers ${icon('arrow')}</a></div><div class="step"><div class="step-num">03 / STOCK</div><h3>Record your starting stock</h3><p>Enter opening quantities before your first delivery or usage.</p><a class="btn small" href="#/transactions">View transactions ${icon('arrow')}</a></div></div></div>`:`<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Time to restock</h2><p>Ingredients that need a little attention</p></div><a class="quiet-link" href="#/ingredients">View all →</a></div>${low.length?low.slice(0,5).map(i=>`<div class="stock-row"><div class="item-icon">${icon('leaf')}</div><div><strong>${e(i.name)}</strong><small>Reorder below ${fmt(i.reorder_point)} ${e(i.base_unit)}</small></div><div class="stock-qty number"><strong>${fmt(i.quantity_on_hand)} ${e(i.base_unit)}</strong><div class="stock-bar"><span style="width:${Math.min(100,Number(i.quantity_on_hand)/Math.max(1,Number(i.reorder_point))*100)}%"></span></div><small>Low stock</small></div></div>`).join(''):empty('Stock looks good','No active ingredients are below their reorder point.')}</section><section class="panel"><div class="panel-header"><div><h2>Recent activity</h2><p>Your latest stock changes</p></div><a class="quiet-link" href="#/transactions">View all →</a></div>${state.transactions.length?state.transactions.slice(0,4).map(m=>`<div class="activity"><span class="activity-icon">${icon(Number(m.quantity_change)>0?'down':'up')}</span><div><strong>${e(item(m.item_id)?.name||'Ingredient')}</strong><p>${e(label(m.movement_type))} · ${date(m.created_at,true)}</p></div><div class="activity-value number ${Number(m.quantity_change)>0?'positive':'negative'}">${Number(m.quantity_change)>0?'+':''}${fmt(m.quantity_change)} ${e(item(m.item_id)?.base_unit||'')}</div></div>`).join(''):empty('No stock activity yet','Record opening stock or receive your first delivery.')}</section></div>`}<section class="panel section-gap"><div class="panel-header"><div><h2>On the way</h2><p>Open purchase orders and expected deliveries</p></div><a class="quiet-link" href="#/orders">View orders →</a></div>${orderTable(orders.slice(0,5))}</section><p class="subtle-note">${state.demo?'Fictional sample data · October 29, 2026':state.updated?`Last refreshed ${date(state.updated,true)} · Refresh to check for changes made by your team.`:''}</p>`;
}
function searchBox(placeholder){return `<div class="search">${icon('search')}<input id="page-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${e(state.search)}"></div>`;}
function ingredients(){const rows=state.data.inventory_levels.filter(i=>(`${i.name} ${i.sku} ${i.category}`).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||state.filter==='low'&&i.is_low_stock||state.filter==='active'&&i.is_active||state.filter==='archived'&&!i.is_active)).sort((a,b)=>a.name.localeCompare(b.name));return `${heading('Ingredients','Know what you have, what you use, and what needs replenishing.',canManage()?'<button class="btn primary" data-action="new-item">'+icon('plus')+' Add ingredient</button>':'')}${ownerStockChart()}<div class="toolbar">${searchBox('Search ingredients…')}<div class="filters"><select id="page-filter" aria-label="Stock filter">${[['all','All ingredients'],['low','Low stock'],['active','Active'],['archived','Archived']].map(([v,t])=>`<option value="${v}" ${state.filter===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Category</th><th>On hand</th><th>Reorder point</th><th>Status</th><th class="align-right">Action</th></tr></thead><tbody>${rows.map(i=>`<tr><td><div class="item-cell"><div class="item-icon">${icon('leaf')}</div><div><strong>${e(i.name)}</strong><small>${e(i.sku)}</small></div></div></td><td>${e(i.category)}</td><td class="number"><strong>${fmt(i.quantity_on_hand)}</strong> ${e(i.base_unit)}</td><td>${fmt(i.reorder_point)} ${e(i.base_unit)}</td><td><span class="tag ${i.is_low_stock?'warning':i.is_active?'good':''}"><span class="dot"></span>${!i.is_active?'Archived':i.is_low_stock?'Low stock':'In range'}</span></td><td class="align-right"><button class="btn small" data-action="item-detail" data-id="${e(i.item_id)}">Details</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${rows.length} ingredient${rows.length===1?'':'s'}</span><span>Quantities are in each ingredient’s base unit.</span></div>`:empty(state.search||state.filter!=='all'?'No matching ingredients':'Your ingredient list starts here',state.search?'Try another search.':'Add an ingredient, then record its opening stock.')}</div>`;}
function suppliersPage(){const rows=state.data.suppliers.filter(s=>(s.name+' '+(s.contact_name||'')).toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));return `${heading('Your supply network','Keep supplier contacts, pack sizes, and current quotes together.',canManage()?'<button class="btn primary" data-action="new-supplier">'+icon('plus')+' Add supplier</button>':'')}<div class="toolbar">${searchBox('Search suppliers…')}<span class="muted">${rows.length} supplier${rows.length===1?'':'s'}</span></div>${rows.length?`<div class="supplier-grid">${rows.map(s=>`<article class="panel supplier-card"><div class="supplier-title"><span class="avatar">${e(s.name.split(' ').map(w=>w[0]).join('').slice(0,2))}</span><div><h3>${e(s.name)}</h3><span class="tag ${s.is_active?'good':''}">${s.is_active?'Active':'Archived'}</span></div></div><div class="supplier-details"><p class="row">${icon('mail')}${e(s.contact_email||'No email added')}</p><p class="row">${icon('phone')}${e(s.contact_phone||'No phone added')}</p><p class="row">${icon('clock')}${s.lead_time_days} day${s.lead_time_days===1?'':'s'} lead time</p></div><div class="supplier-footer"><small>${state.data.supplier_items.filter(c=>c.supplier_id===s.id).length} catalog items</small><button class="btn small" data-action="supplier-detail" data-id="${e(s.id)}">View supplier ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="panel">${empty('Build your supply network','Add a supplier before creating your first purchase order.')}</div>`}`;}
function orderTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Supplier</th><th>Expected</th><th>Status</th><th class="align-right">Order total</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${e(o.order_number)}</strong><small>Ordered ${date(o.ordered_at)}</small></td><td>${e(supplier(o.supplier_id)?.name||'Supplier')}</td><td>${date(o.expected_on)}</td><td>${statusTag(o.status)}</td><td class="align-right number">${money(total(o))}</td><td class="align-right"><button class="btn small" data-action="order-detail" data-id="${e(o.id)}">View order</button></td></tr>`).join('')}</tbody></table></div>`:empty('No orders to show','Orders appear here when you start purchasing.');}
function ordersPage(){const rows=state.data.purchase_orders.filter(o=>(o.order_number+' '+(supplier(o.supplier_id)?.name||'')).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||state.filter==='open'&&['ordered','partially_received'].includes(o.status)||state.filter===o.status)).sort((a,b)=>b.ordered_at.localeCompare(a.ordered_at));return `${heading('Purchase orders','Plan your purchases. Follow every order through to delivery.',canManage()?'<button class="btn primary" data-action="new-order">'+icon('plus')+' New purchase order</button>':'')}<div class="toolbar">${searchBox('Search orders or suppliers…')}<select id="page-filter" aria-label="Order status">${[['all','All orders'],['open','Open orders'],['received','Received'],['cancelled','Cancelled']].map(([v,t])=>`<option value="${v}" ${state.filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="panel">${orderTable(rows)}</div><p class="subtle-note">Order totals use the recorded price per base unit. Taxes, freight, payments, and invoices are not included.</p>`;}
function receivingPage(){const orders=openOrders().sort((a,b)=>(a.expected_on||'9999').localeCompare(b.expected_on||'9999'));const receipts=[...state.data.goods_receipts].sort((a,b)=>b.received_at.localeCompare(a.received_at));return `${heading('Receive with confidence','Record what actually arrived, even when an order comes in parts.',canManage()||state.demo?'<button class="btn primary" data-action="scan-invoice">'+icon('plus')+' Upload invoice PDF</button>':'')}<div class="invoice-receiving-note"><strong>From invoice to inventory</strong><p>Scan a supplier PDF, check the actual delivery, then update stock, order progress, and Receiving together.</p></div><section class="panel"><div class="panel-header"><h2>Awaiting delivery</h2><span class="tag">${orders.length} open orders</span></div>${orders.length?`<div class="table-wrap"><table><thead><tr><th>Order / supplier</th><th>Expected</th><th>Lines complete</th><th>Status</th><th></th></tr></thead><tbody>${orders.map(o=>{const lines=state.data.purchase_order_progress.filter(l=>l.purchase_order_id===o.id),done=lines.filter(l=>Number(l.quantity_outstanding)===0).length;return `<tr><td><strong>${e(o.order_number)}</strong><small>${e(supplier(o.supplier_id)?.name)}</small></td><td>${date(o.expected_on)}</td><td>${done} / ${lines.length}<div class="progress-track"><span style="width:${lines.length?done/lines.length*100:0}%"></span></div></td><td>${statusTag(o.status)}</td><td class="align-right"><button class="btn small ${canManage()?'primary':''}" data-action="${canManage()?'receive':'order-detail'}" data-id="${e(o.id)}">${canManage()?'Receive delivery':'View order'}</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('All caught up','There are no open orders waiting for a delivery.')}</section><section class="panel"><div class="panel-header"><div><h2>Delivery history</h2><p>Recorded deliveries, with their individual items</p></div></div>${receipts.length?`<div class="table-wrap"><table><thead><tr><th>Received</th><th>Purchase order</th><th>Items received</th><th>Notes</th><th></th></tr></thead><tbody>${receipts.map(r=>`<tr><td>${date(r.received_at,true)}</td><td>${e(state.data.purchase_orders.find(o=>o.id===r.purchase_order_id)?.order_number)}</td><td>${state.data.goods_receipt_lines.filter(l=>l.receipt_id===r.id).length} lines</td><td>${e(r.notes||'—')}</td><td><button class="btn small" data-action="receipt-detail" data-id="${e(r.id)}">Details</button></td></tr>`).join('')}</tbody></table></div>`:empty('No deliveries recorded','Confirm a delivery against an open purchase order to get started.')}</section>`;}
function transactionsPage(){return `${heading('Every change, accounted for.','A running record of what came in, what was used, and what was lost.',canStock()?'<button class="btn primary" data-action="new-movement">'+icon('plus')+' Record transaction</button>':'')}<div class="toolbar"><div class="filters"><select id="tx-item" aria-label="Filter by ingredient"><option value="">All ingredients</option>${state.data.inventory_items.map(i=>`<option value="${e(i.id)}" ${state.txItem===i.id?'selected':''}>${e(i.name)}</option>`).join('')}</select><select id="tx-type" aria-label="Filter by transaction type"><option value="">All transaction types</option>${['opening','receipt','usage','waste','adjustment'].map(t=>`<option ${state.txType===t?'selected':''} value="${t}">${label(t)}</option>`).join('')}</select></div><button class="btn small" data-action="export-transactions">${icon('download')} Export this page</button></div><div class="panel">${state.transactions.length?`<div class="table-wrap"><table><thead><tr><th>When</th><th>Ingredient</th><th>Type</th><th class="align-right">Change</th><th>Reason / reference</th></tr></thead><tbody>${state.transactions.map(m=>`<tr><td class="nowrap">${date(m.created_at,true)}</td><td><strong>${e(item(m.item_id)?.name||'Ingredient')}</strong><small>${e(item(m.item_id)?.sku||'')}</small></td><td><span class="tag ${m.movement_type==='waste'?'warning':Number(m.quantity_change)>0?'good':''}">${label(m.movement_type)}</span></td><td class="align-right number ${Number(m.quantity_change)>0?'positive':'negative'}"><strong>${Number(m.quantity_change)>0?'+':''}${fmt(m.quantity_change)}</strong> ${e(item(m.item_id)?.base_unit||'')}</td><td>${e(m.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching transactions','Try another filter, record opening stock, or receive a delivery.')}<div class="table-footer"><span>${state.transactionCount} transaction${state.transactionCount===1?'':'s'} · Page ${state.transactionPage+1} of ${Math.max(1,Math.ceil(state.transactionCount/25))}</span><div class="row"><button class="btn small" data-action="tx-prev" ${!state.transactionPage||state.loading?'disabled':''}>Previous</button><button class="btn small" data-action="tx-next" ${(state.transactionPage+1)*25>=state.transactionCount||state.loading?'disabled':''}>Next</button></div></div></div><p class="subtle-note">Stock transactions preserve the history of inventory changes. Record an adjustment with a reason to correct a balance; existing entries are not edited or deleted.</p>`;}
function pendingRequests(){if(state.demo||!state.session)return [];const prefix=`gateway-request:${state.session.user.id}:${state.restaurant.id}:`;try{return Object.keys(sessionStorage).filter(k=>k.startsWith(prefix)).map(k=>({key:k,action:k.slice(prefix.length),...JSON.parse(sessionStorage.getItem(k))}));}catch{return [];}}
function workspacePage(){const r=state.restaurant,pending=pendingRequests();return `${heading('Your workspace','Restaurant details, your access, and the rules behind your inventory.')}<div class="info-grid"><section class="panel"><div class="panel-header"><h2>Restaurant</h2><span class="tag">${state.demo?'Sample':'Live data'}</span></div><div class="panel-body"><dl class="definition"><div><dt>Name</dt><dd>${e(r.name)}</dd></div><div><dt>Currency</dt><dd>${e(r.currency)}</dd></div><div><dt>Time zone</dt><dd>${e(r.timezone)}</dd></div><div><dt>Stock locations</dt><dd>One inventory pool</dd></div></dl><p class="subtle-note">Restaurant profile changes and additional member access are managed by the project administrator.</p></div></section><section class="panel"><div class="panel-header"><h2>Your access</h2>${icon('shield')}</div><div class="panel-body"><dl class="definition"><div><dt>Account</dt><dd>${state.demo?'Sample viewer':e(state.session?.user.email)}</dd></div><div><dt>Restaurant role</dt><dd>${state.demo?'Read-only preview':e(label(state.role))}</dd></div></dl><p class="subtle-note">${state.demo?'Sign in to create or join a real restaurant workspace.':manager(state.role)?'You can maintain ingredients and suppliers, place orders, receive deliveries, and record stock transactions.':state.role==='staff'?'You can view restaurant data and record ingredient usage or waste.':'You can view restaurant data. Editing requires an owner, manager, or relevant staff role.'}</p>${!state.demo?'<button class="btn small" style="margin-top:18px" data-action="new-restaurant">'+icon('plus')+' Create another restaurant</button>':''}</div></section></div>${pending.length?`<section class="panel section-gap"><div class="panel-header"><h2>Unconfirmed submissions</h2></div><div class="panel-body">${pending.map(p=>`<div class="pending"><strong>${e(label(p.action.replaceAll('_',' ')))}</strong><p>A connection interruption left this submission unconfirmed. Retrying sends exactly the same request and will not duplicate a successful transaction.</p><button class="btn small" data-action="retry-pending" data-key="${e(p.key)}">Retry original submission</button></div>`).join('')}</div></section>`:''}<section class="panel section-gap"><div class="panel-header"><h2>How your inventory works</h2></div><div class="panel-body"><div class="steps"><div><h3>Order first, receive later</h3><p class="subtle-note">Placing an order does not change inventory. Each delivery adds only the quantities you actually receive.</p></div><div><h3>One unit per ingredient</h3><p class="subtle-note">Inventory uses kg, g, l, ml, or each. Supplier pack sizes help you calculate quantities and prices in that unit.</p></div><div><h3>A history you can follow</h3><p class="subtle-note">Opening stock, deliveries, usage, waste, and adjustments determine the current balance.</p></div></div></div></section><section class="panel"><div class="panel-header"><h2>Current scope</h2></div><div class="panel-body"><p>Purchasing and stock control for one inventory pool per restaurant. Batch expiry, recipe deductions, POS imports, transfers, invoice accounting, and payments are not included. Invoice PDFs can be scanned and reviewed in Receiving to record a delivery. Low-stock flags are based on your reorder points; they do not send notifications or place orders.</p></div></section>`;}
function render(){if(!activePages()[state.page])state.page='home';if(state.portal==='supplier'){renderSupplier();return;}document.title=`${state.session||state.demo?activePages()[state.page][0]:'Welcome'} · Gateway Inventory`;if(!state.session&&!state.demo){app.innerHTML=landing();return;}if(!state.demo&&!state.restaurant){app.innerHTML=state.loading?'<main id="main" class="boot"><span class="brand-mark">g.</span><p>Loading your restaurant memberships…</p></main>':onboarding();return;}const content=state.data?({home,ingredients,suppliers:suppliersPage,orders:ordersPage,receiving:receivingPage,transactions:transactionsPage,workspace:workspacePage}[state.page])():empty(state.loading?'Loading your workspace…':'Workspace unavailable',state.loading?'Getting your latest restaurant data.':'Please use Refresh to try again.');app.innerHTML=shell(content);}
async function refreshTransactions(){if(state.portal==='supplier')return;if(state.demo){const rows=demoTransactions.filter(m=>(!state.txItem||m.item_id===state.txItem)&&(!state.txType||m.movement_type===state.txType));state.transactionCount=rows.length;state.transactions=rows.slice(state.transactionPage*25,state.transactionPage*25+25);return;}const rid=state.restaurant.id,ticket=epoch;const result=await getTransactions(rid,{page:state.transactionPage,item:state.txItem,type:state.txType});if(ticket!==epoch||state.restaurant?.id!==rid)return;state.transactions=result.rows;state.transactionCount=result.count;}
async function refresh(){if(state.portal==='supplier'){await refreshSupplier();return;}if(state.demo){await refreshTransactions();render();return;}if(!state.restaurant)return;const current=++epoch,rid=state.restaurant.id;state.loading=true;state.error='';render();try{const data=await loadWorkspace(rid);if(current!==epoch)return;state.data=data;state.role=data.restaurant_members.find(m=>m.user_id===state.session?.user.id)?.role||'viewer';await refreshTransactions();if(current!==epoch)return;state.updated=new Date().toISOString();}catch(error){if(current===epoch)state.error=friendlyError(error);}finally{if(current===epoch){state.loading=false;render();}}}
async function memberships(){if(state.portal==='supplier'){await supplierMemberships();return;}const user=state.session?.user;if(!user)return;const current=++epoch;state.loading=true;render();try{const [rs,ms]=await Promise.all([db.from('restaurants').select('id,name,currency,timezone,is_demo').order('name'),db.from('restaurant_members').select('restaurant_id,user_id,role').eq('user_id',user.id)]);if(rs.error)throw rs.error;if(ms.error)throw ms.error;if(current!==epoch)return;state.restaurants=rs.data;state.memberships=ms.data;let saved;try{saved=localStorage.getItem(`gateway-restaurant:${user.id}`);}catch{}state.restaurant=rs.data.find(r=>r.id===state.restaurant?.id)||rs.data.find(r=>r.id===saved)||rs.data[0]||null;state.role=ms.data.find(m=>m.restaurant_id===state.restaurant?.id)?.role||'viewer';state.error='';state.loading=false;if(state.restaurant)await refresh();else render();}catch(error){if(current!==epoch)return;state.error=friendlyError(error);state.loading=false;render();}}
async function sessionChanged(session){const id=session?.user?.id||null;if(id===authIdentity)return;authIdentity=id;++epoch;state.session=session;state.demo=false;state.supplierSnapshot=null;state.supplierAccounts=[];state.supplierAccount=null;state.restaurant=null;state.data=null;state.transactions=[];state.error='';if(session)await memberships();else render();}
function startDemo(){if(state.portal==='supplier'){++epoch;state.demo=true;state.data=null;state.transactions=[];state.restaurant=null;state.supplierSnapshot=structuredClone(supplierDemoSnapshot);state.supplierAccount=state.supplierSnapshot.account;state.supplierAccounts=[state.supplierAccount];state.loading=false;state.error='';state.page='home';location.hash='/home';render();window.scrollTo(0,0);return;}++epoch;state.demo=true;state.restaurant=demoRestaurant;state.data=structuredClone(demoData);state.transactions=structuredClone(demoTransactions);state.transactionCount=demoTransactions.length;state.transactionPage=0;state.txItem='';state.txType='';state.loading=false;state.error='';state.role='viewer';state.page='home';location.hash='/home';render();window.scrollTo(0,0);}
function showDialog(title,subtitle,body,footer='',wide=false){dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2><p>${e(subtitle)}</p></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer}`;if(!dialog.open)dialog.showModal();}
function field(title,name,value='',type='text',extra='',note=''){return `<label class="field">${title}<input name="${name}" type="${type}" value="${e(value)}" ${extra}>${note?`<small>${note}</small>`:''}</label>`;}
function selectField(title,name,options,value='',extra=''){return `<label class="field">${title}<select name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`).join('')}</select></label>`;}
function formDialog(kind,title,subtitle,fields,data={},wide=false,submit='Save changes'){modalState={kind,id:data.id||crypto.randomUUID(),data,isNew:!data.id,restaurantId:state.restaurant?.id};showDialog(title,subtitle,`<form id="editor-form"><div class="dialog-body">${fields}</div><div class="form-error" id="editor-error" role="alert"></div><div class="dialog-footer"><button type="button" class="btn" data-action="close-dialog">Cancel</button><button class="btn primary" type="submit">${submit}</button></div></form>`,'',wide);}
function editItem(id){if(!canManage())return;const i=item(id)||{};formDialog('item',i.id?'Edit ingredient':'Add ingredient','Keep quantities in one base unit throughout this ingredient’s history.',`<div class="form-grid">${field('Ingredient name','name',i.name,'text','required maxlength="160"')}${field('SKU / internal code','sku',i.sku,'text',`${i.id?'readonly':'required'} maxlength="60"`)}${field('Category','category',i.category||'Other','text','required maxlength="100"')}${selectField('Base unit','base_unit',units.map(u=>[u,u]),i.base_unit||'kg',i.id?'disabled':'')}${field('Reorder point','reorder_point',i.reorder_point??0,'number','required min="0" step="0.001"')}<label class="check"><input type="checkbox" name="is_active" ${i.is_active!==false?'checked':''}>Active ingredient</label></div><p class="subtle-note">Opening stock is recorded separately in Transactions. SKU and base unit stay fixed after creation.</p>`,i,false,i.id?'Save ingredient':'Add ingredient');}
function itemDetail(id){const i=item(id),l=level(id);if(!i)return;showDialog(i.name,`${i.sku} · ${i.category}`,`<div class="dialog-body"><dl class="definition"><div><dt>On hand</dt><dd>${fmt(l?.quantity_on_hand)} ${e(i.base_unit)}</dd></div><div><dt>Reorder point</dt><dd>${fmt(i.reorder_point)} ${e(i.base_unit)}</dd></div><div><dt>Status</dt><dd>${!i.is_active?'Archived':l?.is_low_stock?'Low stock':'In range'}</dd></div><div><dt>Base unit</dt><dd>${e(i.base_unit)}</dd></div></dl><p class="subtle-note">The balance is calculated from stock transactions.</p></div>`,`<div class="dialog-footer"><button class="btn" data-action="item-history" data-id="${e(id)}">View transactions</button>${canStock()&&i.is_active?`<button class="btn" data-action="new-movement" data-id="${e(id)}">Record change</button>`:''}${canManage()?`<button class="btn primary" data-action="edit-item" data-id="${e(id)}">Edit ingredient</button>`:''}</div>`);}
function editSupplier(id){if(!canManage())return;const s=supplier(id)||{};formDialog('supplier',s.id?'Edit supplier':'Add supplier','The people and details behind your next delivery.',`<div class="form-grid">${field('Supplier name','name',s.name,'text','required maxlength="160"')}${field('Contact name','contact_name',s.contact_name,'text','maxlength="160"')}${field('Email address','contact_email',s.contact_email,'email','maxlength="254"')}${field('Phone number','contact_phone',s.contact_phone,'tel','maxlength="50"')}${field('Typical lead time (days)','lead_time_days',s.lead_time_days??0,'number','required min="0" max="3650" step="1"')}<label class="check"><input type="checkbox" name="is_active" ${s.is_active!==false?'checked':''}>Active supplier</label></div>${!s.id?`<section class="supplier-connection-fields" aria-label="Connect supplier account"><h3>Connect their supplier account</h3>${field('Connection code (optional)','supplier_account_id','','text','maxlength="36" autocomplete="off" spellcheck="false" placeholder="Paste the supplier’s connection code"','Ask the supplier for the code in their Workspace. Leave blank to save their details without requesting a connection.')}<p class="subtle-note">Adding a code sends a connection request when you save. After the supplier accepts, they can see orders and delivery receipts placed with this supplier record, including products and prices. Internal stock, usage, waste, and other suppliers stay private.</p></section>`:''}`,s,false,s.id?'Save supplier':'Add supplier');}
function supplierDetail(id){const s=supplier(id);if(!s)return;const catalog=state.data.supplier_items.filter(c=>c.supplier_id===id);showDialog(s.name,`${s.lead_time_days} day lead time · ${s.is_active?'Active supplier':'Archived supplier'}`,`<div class="dialog-body"><div class="row spread"><p>${e(s.contact_name||'No contact name')}<br>${e(s.contact_email||'No email')} · ${e(s.contact_phone||'No phone')}</p>${canManage()?`<button class="btn small" data-action="edit-supplier" data-id="${e(id)}">${icon('edit')} Edit supplier</button>`:''}</div>${canManage()?`<div class="connection-note"><p>Link this supplier’s account to share your orders and delivery receipts.</p><button class="btn small" data-action="connect-supplier" data-id="${e(id)}">Manage connection</button></div>`:''}<div class="row spread" style="margin:25px 0 12px"><h3>Supplier catalog</h3>${canManage()?`<button class="btn small" data-action="new-catalog" data-supplier="${e(id)}">${icon('plus')} Add catalog item</button>`:''}</div>${catalog.length?`<div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Pack size</th><th>Pack price</th><th>Base-unit price</th>${canManage()?'<th></th>':''}</tr></thead><tbody>${catalog.map(c=>`<tr><td>${e(item(c.item_id)?.name)}</td><td>${fmt(c.base_units_per_pack)} ${e(item(c.item_id)?.base_unit)} / ${e(c.purchase_unit)}</td><td>${money(c.quoted_pack_price)}</td><td>${money(Number(c.quoted_pack_price)/Number(c.base_units_per_pack))} / ${e(item(c.item_id)?.base_unit)}</td>${canManage()?`<td><button class="btn small" data-action="edit-catalog" data-id="${e(c.id)}">Edit</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('No catalog items yet','Connect an ingredient to this supplier, with its pack size and quote.')}</div>`,'',true);}
function editCatalog(id,supplierId){if(!canManage())return;const c=state.data.supplier_items.find(c=>c.id===id)||{supplier_id:supplierId};const eligible=state.data.inventory_items.filter(i=>i.is_active||i.id===c.item_id);if(!eligible.length){toast('Add an ingredient before creating a catalog item.',true);return;}formDialog('catalog',c.id?'Edit catalog item':'Add catalog item','Pack sizes and quotes help you prepare purchase orders.',`<div class="form-grid">${selectField('Supplier','supplier_id',state.data.suppliers.map(s=>[s.id,s.name]),c.supplier_id,'disabled')}${selectField('Ingredient','item_id',eligible.map(i=>[i.id,`${i.name} (${i.base_unit})`]),c.item_id,c.id?'disabled':'')}${field('Supplier’s item code (optional)','supplier_sku',c.supplier_sku,'text','maxlength="80"')}${field('Purchase unit','purchase_unit',c.purchase_unit||'case','text','required maxlength="40"','For example: case, bag, tray.')}${field('Base units per pack','base_units_per_pack',c.base_units_per_pack||1,'number','required min="0.001" step="0.001"','For a 5 kg case, enter 5 when the ingredient unit is kg.')}${field('Quoted price per pack','quoted_pack_price',c.quoted_pack_price??0,'number','required min="0" step="0.0001"')}</div>`,c,false,'Save catalog item');}
function movementForm(itemId){if(!canStock())return;const active=state.data.inventory_items.filter(i=>i.is_active);if(!active.length){toast('Add an ingredient first.',true);return;}const types=manager(state.role)?['usage','waste','opening','adjustment']:['usage','waste'];formDialog('movement','Record stock transaction','Record what changed and why. Incoming deliveries belong in Receiving.',`<div class="form-grid">${selectField('Ingredient','item_id',active.map(i=>[i.id,`${i.name} (${i.base_unit})`]),itemId||active[0].id)}${selectField('Transaction type','movement_type',types.map(t=>[t,label(t)]))}${field('Quantity in the ingredient’s base unit','quantity','','number','required step="0.001"','Use a positive quantity for usage, waste, or opening. Adjustments can be positive or negative.')}<label class="field full">Reason<textarea name="reason" maxlength="500" required placeholder="For example, dinner preparation or damaged produce"></textarea></label></div><p class="subtle-note">Opening stock must be the first transaction for an ingredient. Usage and waste are subtracted automatically.</p>`,{},false,'Record transaction');}
function orderLineMarkup(){const active=state.data.inventory_items.filter(i=>i.is_active);return `<div class="line-editor">${selectField('Ingredient','line_item',[['','Select ingredient'],...active.map(i=>[i.id,`${i.name} (${i.base_unit})`])])}${field('Quantity','line_quantity','1','number','required min="0.001" step="0.001"','In base units')}${field('Price per base unit','line_price','0','number','required min="0" step="0.0001"','Not price per pack')}<button type="button" class="icon-button" data-action="remove-line" aria-label="Remove ingredient line">${icon('close')}</button></div>`;}
function newOrder(){if(!canManage())return;const active=state.data.suppliers.filter(s=>s.is_active);if(!active.length||!state.data.inventory_items.some(i=>i.is_active)){toast('Add an active supplier and ingredient before placing an order.',true);return;}formDialog('order','New purchase order','Quantities and prices are in each ingredient’s base unit. Stock changes when a delivery is received.',`<div class="form-grid">${selectField('Supplier','supplier_id',active.map(s=>[s.id,s.name]))}${field('Order number','order_number',`PO-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${crypto.randomUUID().slice(0,4).toUpperCase()}`,'text','required maxlength="80"')}${field('Expected delivery (optional)','expected_on','','date')}<label class="field">Notes<textarea name="notes" maxlength="1000" placeholder="Delivery notes or instructions"></textarea></label></div><div style="margin-top:20px" id="order-lines">${orderLineMarkup()}</div><button class="btn small" type="button" data-action="add-line">${icon('plus')} Add another ingredient</button><div class="dialog-summary"><span>Order total</span><strong id="order-total">${money(0)}</strong></div><p class="subtle-note">Selecting an ingredient uses its supplier quote when available. Review the price before submitting.</p>`,{},true,'Create purchase order');}
function orderDetail(id){const o=state.data.purchase_orders.find(o=>o.id===id);if(!o)return;const lines=state.data.purchase_order_progress.filter(l=>l.purchase_order_id===id);showDialog(o.order_number,`${supplier(o.supplier_id)?.name} · Ordered ${date(o.ordered_at)}`,`<div class="dialog-body"><div class="row spread">${statusTag(o.status)}<span class="muted">Expected ${date(o.expected_on)}</span></div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Ingredient</th><th>Ordered</th><th>Received</th><th>Outstanding</th><th class="align-right">Unit price</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${e(item(l.item_id)?.name)}</td><td>${fmt(l.quantity_ordered)} ${e(l.base_unit)}</td><td>${fmt(l.quantity_received)}</td><td>${o.status==='cancelled'?'Cancelled':fmt(l.quantity_outstanding)}</td><td class="align-right">${money(l.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="dialog-summary"><span>Order total</span><strong>${money(total(o))}</strong></div>${o.notes?`<p class="subtle-note">${e(o.notes)}</p>`:''}</div>`,`<div class="dialog-footer">${canManage()&&o.status==='ordered'?`<button class="btn danger" data-action="cancel-order" data-id="${e(id)}">Cancel order</button>`:''}${canManage()&&['ordered','partially_received'].includes(o.status)?`<button class="btn primary" data-action="receive" data-id="${e(id)}">${icon('box')} Receive delivery</button>`:''}<button class="btn" data-action="close-dialog">Close</button></div>`,true);}
function receiveForm(id){if(!canManage())return;const o=state.data.purchase_orders.find(o=>o.id===id);if(!o)return;const lines=state.data.purchase_order_progress.filter(l=>l.purchase_order_id===id&&Number(l.quantity_outstanding)>0);formDialog('receive',`Receive ${o.order_number}`,`From ${supplier(o.supplier_id)?.name}. Enter only what arrived in this delivery.`,`${lines.map(l=>`<div class="receipt-editor" data-line="${e(l.purchase_order_line_id)}"><div><strong>${e(item(l.item_id)?.name)}</strong><p>${fmt(l.quantity_outstanding)} ${e(l.base_unit)} still outstanding</p></div><span class="outstanding muted">${fmt(l.quantity_received)} received</span>${field(`Received now (${e(l.base_unit)})`,'received','0','number',`required min="0" max="${Number(l.quantity_outstanding)}" step="0.001"`)}</div>`).join('')}<label class="field" style="margin-top:20px">Delivery notes<textarea name="notes" maxlength="1000" placeholder="Optional notes about this delivery"></textarea></label><p class="subtle-note">Leave zero for items that did not arrive. The delivery and its stock changes are saved together.</p>`,{orderId:id},true,'Confirm delivery');}
function receiptDetail(id){const r=state.data.goods_receipts.find(r=>r.id===id);if(!r)return;const o=state.data.purchase_orders.find(o=>o.id===r.purchase_order_id);showDialog('Delivery details',`${o?.order_number} · ${date(r.received_at,true)}`,`<div class="dialog-body"><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Received</th></tr></thead><tbody>${state.data.goods_receipt_lines.filter(l=>l.receipt_id===id).map(l=>`<tr><td>${e(item(l.item_id)?.name)}</td><td>${fmt(l.quantity_received)} ${e(item(l.item_id)?.base_unit)}</td></tr>`).join('')}</tbody></table></div><p class="subtle-note">${e(r.notes||'No delivery notes.')}</p></div>`);}
function restaurantForm(){if(state.demo)return;formDialog('restaurant','Create another restaurant','The new restaurant starts empty, with you as its owner.',field('Restaurant name','name','','text','required maxlength="160"'),{},false,'Create restaurant');}
function updateOrderTotal(){if(modalState?.kind!=='order')return;let n=0;dialog.querySelectorAll('.line-editor').forEach(row=>{n+=(Number(row.querySelector('[name=line_quantity]').value)||0)*(Number(row.querySelector('[name=line_price]').value)||0);});dialog.querySelector('#order-total').textContent=money(n);}
function applyQuote(row){const iid=row.querySelector('[name=line_item]').value,sid=dialog.querySelector('[name=supplier_id]').value;const quote=state.data.supplier_items.find(c=>c.item_id===iid&&c.supplier_id===sid);row.querySelector('[name=line_price]').value=quote?(Number(quote.quoted_pack_price)/Number(quote.base_units_per_pack)).toFixed(4):'0';updateOrderTotal();}

function supplierEditorButton(form,m){
 const code=form.querySelector('[name=supplier_account_id]')?.value.trim();
 form.querySelector('[type=submit]').textContent=code?(m.isNew?'Add & request connection':'Save & request connection'):(m.isNew?'Add supplier':'Save supplier');
}
async function submitSupplierEditor(form,m){
 if(m.submitting)return;
 const uid=state.session?.user.id,rid=m.restaurantId,f=new FormData(form),str=n=>String(f.get(n)||'').trim(),errorBox=form.querySelector('#editor-error');
 const controls=[...form.querySelectorAll('input,button'),dialog.querySelector('[aria-label="Close dialog"]')].filter(Boolean),submit=form.querySelector('[type=submit]');
 const current=()=>modalState===m&&state.portal==='owner'&&!state.demo&&state.session?.user.id===uid&&state.restaurant?.id===rid;
 errorBox.textContent='';
 try{
  if(!uid||!current()||!canManage())throw new Error('Sign in as an owner or manager of this restaurant to save a supplier.');
  if(!str('name'))throw new Error('Enter a supplier name.');
  const values={name:str('name'),contact_name:str('contact_name')||null,contact_email:str('contact_email')||null,contact_phone:str('contact_phone')||null,lead_time_days:decimal(str('lead_time_days'),'Lead time',{places:0,max:3650}),is_active:f.has('is_active')};
  m.submitting=true;form.setAttribute('aria-busy','true');controls.forEach(el=>el.disabled=true);submit.textContent=str('supplier_account_id')?'Saving & requesting…':'Saving supplier…';
  const result=await saveSupplierWithConnection({draft:m,restaurantId:rid,values,code:str('supplier_account_id'),saveSupplier:(id,restaurantId,details,isNew)=>saveRecord('suppliers',id,restaurantId,details,isNew),requestConnection:async(restaurantId,supplierId,accountId)=>{
   if(!current())throw new Error('Your workspace changed. Return to this restaurant before requesting a connection.');
   const {error}=await db.rpc('request_supplier_connection',{p_restaurant_id:restaurantId,p_supplier_id:supplierId,p_supplier_account_id:accountId});if(error)throw error;
  }});
  if(!current())return;
  dialog.close();modalState=null;toast(result.connectionRequested?'Supplier saved. Connection request sent — waiting for supplier approval.':'Supplier saved to your restaurant workspace.');await refresh();
 }catch(error){
  if(current()){errorBox.textContent=friendlyError(error);if(m.saved)await refresh();}
 }finally{
  m.submitting=false;form.removeAttribute('aria-busy');controls.forEach(el=>el.disabled=false);supplierEditorButton(form,m);
 }
}

async function submitEditor(form){const m=modalState;if(!m)return;if(m.kind==='supplier')return submitSupplierEditor(form,m);const submit=form.querySelector('[type=submit]'),errorBox=form.querySelector('#editor-error');errorBox.textContent='';submit.disabled=true;form.setAttribute('aria-busy','true');const f=new FormData(form),str=n=>String(f.get(n)||'').trim();try{if(m.kind!=='password'&&m.restaurantId!==state.restaurant?.id)throw new Error('Your restaurant changed. Close this form and try again.');const rid=state.restaurant?.id;const uid=state.session?.user.id;if(!uid||state.demo)throw new Error('Sign in to make changes.');switch(m.kind){case 'connection':{if(!canManage())throw new Error('Manager access required.');const code=str('supplier_account_id');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(code))throw new Error('Enter the supplier’s full connection code.');const {error}=await db.rpc('request_supplier_connection',{p_restaurant_id:rid,p_supplier_id:m.data.supplierId,p_supplier_account_id:code});if(error)throw error;break;}case 'item':{if(!canManage())throw new Error('Manager access required.');const values={name:str('name'),category:str('category'),reorder_point:decimal(str('reorder_point'),'Reorder point'),is_active:f.has('is_active')};if(m.isNew){values.sku=str('sku');values.base_unit=str('base_unit');}await saveRecord('inventory_items',m.id,rid,values,m.isNew);break;}case 'catalog':{if(!canManage())throw new Error('Manager access required.');const values={supplier_sku:str('supplier_sku')||null,purchase_unit:str('purchase_unit'),base_units_per_pack:decimal(str('base_units_per_pack'),'Pack quantity',{positive:true}),quoted_pack_price:decimal(str('quoted_pack_price'),'Pack price',{places:4,max:9999999999.9999})};if(m.isNew){values.supplier_id=m.data.supplier_id;values.item_id=str('item_id');}await saveRecord('supplier_items',m.id,rid,values,m.isNew);break;}case 'movement':{const iid=str('item_id'),type=str('movement_type');const q=movementChange(type,str('quantity'),state.role);if(!str('reason'))throw new Error('Please enter a reason.');if(q<0&&Number(level(iid)?.quantity_on_hand)+q<0)throw new Error('This would reduce inventory below zero. Refresh your stock and check the quantity.');await rpcWrite(uid,rid,'record_stock_movement',{p_restaurant_id:rid,p_item_id:iid,p_type:type,p_quantity_change:q,p_reason:str('reason')});break;}case 'order':{if(!canManage())throw new Error('Manager access required.');const rows=[...dialog.querySelectorAll('.line-editor')].map(row=>({item_id:row.querySelector('[name=line_item]').value,quantity:row.querySelector('[name=line_quantity]').value,unit_price:row.querySelector('[name=line_price]').value}));const lines=orderLines(rows,state.data.inventory_items);await rpcWrite(uid,rid,'create_purchase_order',{p_restaurant_id:rid,p_supplier_id:str('supplier_id'),p_order_number:str('order_number'),p_lines:lines,p_expected_on:str('expected_on')||null,p_notes:str('notes')||null});break;}case 'receive':{if(!canManage())throw new Error('Manager access required.');const rows=[...dialog.querySelectorAll('.receipt-editor')].map(row=>({purchase_order_line_id:row.dataset.line,quantity:row.querySelector('input').value}));const lines=receiptLines(rows,state.data.purchase_order_progress.filter(l=>l.purchase_order_id===m.data.orderId));await rpcWrite(uid,rid,'receive_purchase_order',{p_restaurant_id:rid,p_order_id:m.data.orderId,p_lines:lines,p_notes:str('notes')||null});break;}case 'restaurant':{const {error}=await db.rpc('create_restaurant',{p_name:str('name')});if(error)throw error;dialog.close();modalState=null;toast('Restaurant created.');await memberships();return;}case 'password':{if(str('password')!==str('confirm'))throw new Error('The passwords do not match.');const {error}=await db.auth.updateUser({password:str('password')});if(error)throw error;break;}default:throw new Error('Unknown form.');}dialog.close();modalState=null;toast('Saved to your restaurant workspace.');await refresh();}catch(error){errorBox.textContent=friendlyError(error);}finally{submit.disabled=false;form.removeAttribute('aria-busy');}}
async function cancelOrder(id){const o=state.data.purchase_orders.find(o=>o.id===id);showDialog('Cancel this order?',`${o.order_number} · ${supplier(o.supplier_id)?.name}`,`<div class="dialog-body"><p>This order will be marked cancelled. No stock quantities will change. Only orders with no deliveries can be cancelled.</p><div class="form-error" id="cancel-error" role="alert" style="margin:15px 0 0"></div></div>`,`<div class="dialog-footer"><button class="btn" data-action="order-detail" data-id="${e(id)}">Keep order</button><button class="btn danger" data-action="confirm-cancel" data-id="${e(id)}">Cancel purchase order</button></div>`);}
async function authSubmit(form){const button=form.querySelector('[type=submit]');button.disabled=true;const f=new FormData(form),email=String(f.get('email')).trim(),password=String(f.get('password')||'');try{if(!db)throw new Error('The sign-in service could not load. Please refresh.');let result;if(state.authMode==='reset'){result=await db.auth.resetPasswordForEmail(email,{redirectTo:SITE_URL});if(result.error)throw result.error;state.authNote='If this address has an account, a password reset link will arrive shortly. Check your spam folder too.';}else if(state.authMode==='signup'){result=await db.auth.signUp({email,password,options:{emailRedirectTo:SITE_URL}});if(result.error)throw result.error;if(!result.data.session){state.authNote='Check your email for a confirmation link. After confirming, return here and sign in.';state.authMode='login';}else{await sessionChanged(result.data.session);return;}}else{result=await db.auth.signInWithPassword({email,password});if(result.error)throw result.error;await sessionChanged(result.data.session);return;}state.authError='';render();}catch(error){state.authError=friendlyError(error);const target=form.querySelector('.form-error');if(target)target.textContent=state.authError;}finally{button.disabled=false;}}
async function createFirstRestaurant(form){const b=form.querySelector('button[type=submit]');b.disabled=true;try{const name=new FormData(form).get('name').trim();if(!name)throw new Error('Enter a restaurant name.');const {error}=await db.rpc('create_restaurant',{p_name:name});if(error)throw error;state.error='';await memberships();}catch(error){state.error=friendlyError(error);form.querySelector('.form-error').textContent=state.error;}finally{b.disabled=false;}}
async function actionHandler(event){const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;try{if(state.portal==='supplier'&&!['demo','exit-demo','auth-mode','logout','refresh','reload-membership','menu','close-dialog','switch-portal','choose-portal','supplier-order','supplier-orders','supplier-accept','supplier-decline','supplier-revoke','new-supplier-account'].includes(a))return;switch(a){case 'new-supplier-account':newSupplierAccount();break;case 'choose-portal':await choosePortal(el.dataset.portal);break;case 'switch-portal':showDialog('Choose your workspace','The same login can have different business memberships.',`<div class="dialog-body">${portalChoices()}</div>`);break;case 'connect-supplier':await connectionForm(id);break;case 'owner-revoke':{if(!canManage())return;const {error}=await db.rpc('respond_supplier_connection',{p_connection_id:id,p_status:'revoked'});if(error)throw error;dialog.close();toast('Supplier access disconnected.');break;}case 'supplier-order':{const d=supplierOrderBody(state.supplierSnapshot,id);if(d)showDialog(d.title,d.subtitle,d.body,'',true);break;}case 'supplier-orders':state.supplierRestaurant=id;state.search='';navigate('orders');break;case 'supplier-accept':case 'supplier-decline':case 'supplier-revoke':{if(state.demo){toast('This is a read-only sample.');break;}el.disabled=true;const {error}=await db.rpc('respond_supplier_connection',{p_connection_id:id,p_status:a==='supplier-accept'?'accepted':a==='supplier-decline'?'declined':'revoked'});if(error)throw error;await refreshSupplier();break;}case 'demo':startDemo();break;case 'exit-demo':state.demo=false;state.supplierSnapshot=null;state.supplierAccount=null;state.data=null;state.restaurant=null;if(state.session)await memberships();else render();break;case 'auth-mode':state.authMode=el.dataset.mode;state.authError='';state.authNote='';render();break;case 'logout':{const {error}=await db.auth.signOut({scope:'local'});if(error)throw error;await sessionChanged(null);break;}case 'refresh':await refresh();break;case 'reload-membership':await memberships();break;case 'menu':document.getElementById('sidebar').classList.toggle('open');break;case 'new-item':editItem();break;case 'edit-item':editItem(id);break;case 'item-detail':itemDetail(id);break;case 'new-supplier':editSupplier();break;case 'edit-supplier':editSupplier(id);break;case 'supplier-detail':supplierDetail(id);break;case 'new-catalog':editCatalog(null,el.dataset.supplier);break;case 'edit-catalog':editCatalog(id);break;case 'new-movement':movementForm(id);break;case 'new-order':newOrder();break;case 'order-detail':orderDetail(id);break;case 'scan-invoice':if(canManage()||state.demo)openInvoice({getContext:()=>state,onSaved:async()=>{toast('Invoice recorded. Stock, order progress, and Receiving updated.');await refresh();}});break;case 'receive':receiveForm(id);break;case 'receipt-detail':receiptDetail(id);break;case 'new-restaurant':restaurantForm();break;case 'close-dialog':if(modalState?.submitting)return;dialog.close();modalState=null;break;case 'add-line':if(dialog.querySelectorAll('.line-editor').length<100)dialog.querySelector('#order-lines').insertAdjacentHTML('beforeend',orderLineMarkup());break;case 'remove-line':if(dialog.querySelectorAll('.line-editor').length>1){el.closest('.line-editor').remove();updateOrderTotal();}else toast('Keep at least one ingredient line.');break;case 'item-history':dialog.close();modalState=null;state.txItem=id;state.txType='';state.transactionPage=0;state.page='transactions';await refreshTransactions();navigate('transactions');break;case 'cancel-order':if(canManage())await cancelOrder(id);break;case 'confirm-cancel':{if(!canManage())return;el.disabled=true;const {error}=await db.rpc('cancel_purchase_order',{p_restaurant_id:state.restaurant.id,p_order_id:id});if(error){dialog.querySelector('#cancel-error').textContent=friendlyError(error);el.disabled=false;return;}dialog.close();toast('Purchase order cancelled.');await refresh();break;}case 'tx-prev':case 'tx-next':state.transactionPage+=a==='tx-prev'?-1:1;await refreshTransactions();render();break;case 'retry-pending':{const p=pendingRequests().find(p=>p.key===el.dataset.key);if(!p)return;el.disabled=true;await rpcWrite(state.session.user.id,state.restaurant.id,p.action,JSON.parse(p.payload));toast('Submission confirmed.');await refresh();break;}case 'export-transactions':{const cell=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-]/,"'$&")+'"';const rows=[['Date','Ingredient','Type','Quantity change','Unit','Reason'],...state.transactions.map(m=>[m.created_at,item(m.item_id)?.name,m.movement_type,m.quantity_change,item(m.item_id)?.base_unit,m.reason])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`gateway-transactions-page-${state.transactionPage+1}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}}catch(error){toast(friendlyError(error),true);el.disabled=false;}}
document.addEventListener('click',actionHandler);
document.addEventListener('submit',event=>{if(['auth-form','restaurant-form','editor-form','supplier-account-form'].includes(event.target.id)){event.preventDefault();({ 'auth-form':authSubmit,'restaurant-form':createFirstRestaurant,'editor-form':submitEditor,'supplier-account-form':createSupplierAccount}[event.target.id])(event.target);}});
document.addEventListener('input',event=>{if(event.target.name==='supplier_account_id'&&modalState?.kind==='supplier'&&!modalState.submitting)supplierEditorButton(event.target.form,modalState);if(event.target.id==='page-search'){state.search=event.target.value;const pos=event.target.selectionStart;render();const next=document.getElementById('page-search');next?.focus();next?.setSelectionRange(pos,pos);}if(dialog.open&&modalState?.kind==='order')updateOrderTotal();});
document.addEventListener('change',async event=>{const t=event.target;try{if(t.id==='stock-chart-unit'){state.chartUnit=t.value;render();}else if(t.id==='supplier-currency'){state.chartCurrency=t.value;render();}else if(t.id==='supplier-restaurant'){state.supplierRestaurant=t.value;render();}else if(t.id==='supplier-account-picker'){await switchSupplierAccount(t.value);}else if(t.id==='restaurant-picker'){++epoch;dialog.close();modalState=null;state.restaurant=state.restaurants.find(r=>r.id===t.value);state.data=null;state.transactions=[];state.transactionPage=0;state.txItem='';state.txType='';resetFilters();try{localStorage.setItem(`gateway-restaurant:${state.session.user.id}`,t.value);}catch{}await refresh();}else if(t.id==='page-filter'){state.filter=t.value;render();}else if(t.id==='tx-item'||t.id==='tx-type'){state[t.id==='tx-item'?'txItem':'txType']=t.value;state.transactionPage=0;await refreshTransactions();render();}else if(dialog.open&&modalState?.kind==='order'){if(t.name==='line_item')applyQuote(t.closest('.line-editor'));if(t.name==='supplier_id')dialog.querySelectorAll('.line-editor').forEach(applyQuote);}}catch(error){toast(friendlyError(error),true);}});
window.addEventListener('hashchange',async()=>{const next=route();if(next!==state.page){state.page=next;resetFilters();if(next==='home'){state.transactionPage=0;state.txItem='';state.txType='';try{if(state.data)await refreshTransactions();}catch(error){state.error=friendlyError(error);}}render();window.scrollTo(0,0);}});
dialog.addEventListener('cancel',event=>{if(supplierCreating||modalState?.submitting){event.preventDefault();return;}modalState=null;});
async function boot(){state.page=route();if(!db){state.authError='The sign-in library could not load. Refresh this page to try again.';render();return;}db.auth.onAuthStateChange((event,session)=>{setTimeout(async()=>{if(event==='PASSWORD_RECOVERY'){await sessionChanged(session);formDialog('password','Choose a new password','Use a password of at least 8 characters.',`<div class="form-grid">${field('New password','password','','password','required minlength="8" autocomplete="new-password"')}${field('Confirm password','confirm','','password','required minlength="8" autocomplete="new-password"')}</div>`,{},false,'Update password');}else await sessionChanged(session);},0);});const {data,error}=await db.auth.getSession();if(error)state.authError=friendlyError(error);if(data.session)await sessionChanged(data.session);else{authIdentity=null;render();}}
boot().catch(error=>{state.authError=friendlyError(error);render();});

function portalChoices(){return `<div class="portal-choices" role="group" aria-label="Choose account type"><button type="button" class="portal-choice ${state.portal==='owner'?'selected':''}" aria-pressed="${state.portal==='owner'}" data-action="choose-portal" data-portal="owner">${icon('home')}<strong>Restaurant owner</strong><small>Inventory, purchasing & receiving</small></button><button type="button" class="portal-choice ${state.portal==='supplier'?'selected':''}" aria-pressed="${state.portal==='supplier'}" data-action="choose-portal" data-portal="supplier">${icon('truck')}<strong>Supplier</strong><small>Restaurants, orders & deliveries</small></button></div>`;}
async function choosePortal(portal){if(!['owner','supplier'].includes(portal))return;const wasDemo=state.demo;++epoch;dialog.close();modalState=null;state.portal=portal;try{localStorage.setItem('gateway-portal',portal);}catch{}state.data=null;state.transactions=[];state.restaurant=null;state.restaurants=[];state.supplierSnapshot=null;state.supplierAccount=null;state.supplierAccounts=[];state.supplierRestaurant='';state.page='home';state.loading=false;state.error='';state.authError='';resetFilters();location.hash='/home';if(wasDemo){startDemo();return;}if(state.session)await memberships();else render();}
function ownerStockChart(){const levels=state.data?.inventory_levels||[],choices=[...new Set(levels.filter(i=>i.is_active).map(i=>i.base_unit))];if(!choices.length)return '';const unit=choices.includes(state.chartUnit)?state.chartUnit:choices[0];return `<div class="stock-chart-wrap"><div class="chart-control"><label>Stock unit <select id="stock-chart-unit" aria-label="Stock chart unit">${choices.map(u=>`<option value="${e(u)}" ${u===unit?'selected':''}>${e(u)}</option>`).join('')}</select></label><span class="chart-key"><i></i>On hand <i class="secondary"></i>Reorder point</span></div>${barChart('Stock at a glance',`Up to 10 active ingredients with the lowest balances in ${unit}`,stockRows(levels,unit),{unit,secondaryLabel:'Reorder point'})}</div>`;}
function ownerCharts(){const rows=state.data.inventory_levels.filter(i=>i.is_active);return `<div class="charts-grid">${ownerStockChart()}${donutChart('Stock health','Count of active ingredients · each ingredient counted once',[{label:'In range',value:rows.filter(i=>!i.is_low_stock).length},{label:'Low stock',value:rows.filter(i=>i.is_low_stock).length}])}</div>`;}
function supplierError(error){return ['PGRST202','42P01','42883'].includes(error?.code)?'The supplier workspace is not enabled on this database yet. Ask your project administrator to apply the supplier portal update.':friendlyError(error);}
function rememberSupplierAccount(id){if(!state.demo&&state.session){try{localStorage.setItem(`gateway-supplier:${state.session.user.id}`,id);}catch{}}}
function clearSupplierFilters(){state.supplierRestaurant='';state.search='';state.chartCurrency='USD';state.updated=null;}
async function switchSupplierAccount(id){const account=state.supplierAccounts.find(a=>a.id===id);if(!account)return;++epoch;dialog.close();modalState=null;state.supplierAccount=account;state.supplierSnapshot=null;clearSupplierFilters();rememberSupplierAccount(id);await refreshSupplier();}
async function supplierMemberships(preferredId){if(!state.session)return;const uid=state.session.user.id,current=++epoch;state.loading=true;state.error='';state.supplierSnapshot=null;render();try{const {data,error}=await db.rpc('supplier_portal_accounts');if(error)throw error;if(current!==epoch||state.portal!=='supplier'||state.session?.user.id!==uid)return;state.supplierAccounts=data||[];let savedId;try{savedId=localStorage.getItem(`gateway-supplier:${uid}`);}catch{}const previous=state.supplierAccount?.id;state.supplierAccount=preferredSupplierAccount(state.supplierAccounts,{preferredId,currentId:previous,savedId});if(state.supplierAccount?.id!==previous)clearSupplierFilters();state.loading=false;if(state.supplierAccount){rememberSupplierAccount(state.supplierAccount.id);await refreshSupplier();}else render();}catch(error){if(current===epoch){state.loading=false;state.error=supplierError(error);render();}}}
async function refreshSupplier(){if(state.demo){render();return;}if(!state.supplierAccount)return;const current=++epoch,accountId=state.supplierAccount.id;state.loading=true;state.error='';state.supplierSnapshot=null;render();try{const {data,error}=await db.rpc('supplier_portal_snapshot',{p_supplier_account_id:accountId});if(error)throw error;if(current!==epoch||state.portal!=='supplier'||state.supplierAccount?.id!==accountId)return;state.supplierSnapshot=data;state.updated=new Date().toISOString();}catch(error){if(current===epoch)state.error=supplierError(error);}finally{if(current===epoch){state.loading=false;render();}}}
function supplierBusinessField(){return '<label class="field">Business name<input name="name" required maxlength="160" placeholder="For example, Metro Produce" autocomplete="organization"></label>';}
function newSupplierAccount(){if(state.portal!=='supplier'||state.demo||!state.session||supplierCreating)return;showDialog('Create another supplier','Start a separate supplier business with its own connection code.',`<form id="supplier-account-form"><div class="dialog-body">${supplierBusinessField()}<p class="subtle-note">Your new supplier starts with no restaurant connections or orders. You can switch between your businesses at the top of the page.</p></div><div class="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="btn" data-action="close-dialog">Cancel</button><button class="btn primary" type="submit">Create supplier</button></div></form>`);}
async function createSupplierAccount(form){
 if(supplierCreating)return;
 const uid=state.session?.user.id,errorBox=form.querySelector('.form-error'),submit=form.querySelector('[type=submit]'),originalText=submit.textContent,isDialog=dialog.contains(form),close=isDialog?dialog.querySelector('[aria-label="Close dialog"]'):null;
 try{
  if(!uid||state.demo||state.portal!=='supplier')throw new Error('Sign in to the Supplier portal to create a business.');
  const name=supplierBusinessName(new FormData(form).get('name'));errorBox.textContent='';supplierCreating=true;form.setAttribute('aria-busy','true');form.querySelectorAll('input,button').forEach(el=>el.disabled=true);if(close)close.disabled=true;submit.textContent='Creating supplier…';
  const id=await rpcWrite(uid,'supplier-setup','create_supplier_account',{p_name:name});
  if(state.session?.user.id!==uid||state.portal!=='supplier'||state.demo)return;
  if(isDialog)dialog.close();state.page='workspace';location.hash='/workspace';clearSupplierFilters();
  await supplierMemberships(id);
  if(state.session?.user.id===uid&&state.portal==='supplier')toast(state.supplierAccount?.id===id&&state.supplierSnapshot?'Supplier created. Your new workspace is ready.':'Supplier created. Refresh your supplier memberships to open it.');
 }catch(error){errorBox.textContent=supplierError(error);}finally{supplierCreating=false;form.removeAttribute('aria-busy');form.querySelectorAll('input,button').forEach(el=>el.disabled=false);if(close)close.disabled=false;submit.textContent=originalText;}
}
function supplierOnboarding(){return `<header class="landing-nav">${brand()}<button class="btn small" data-action="logout">Sign out</button></header><main class="onboarding" id="main"><div class="panel panel-body">${portalChoices()}<span class="eyebrow">SUPPLIER SETUP</span><h1>Let’s meet your business.</h1><p>Create a supplier account, then connect with restaurants that work with you.</p><form id="supplier-account-form">${supplierBusinessField()}<div class="form-error" role="alert">${e(state.error)}</div><button class="btn primary full" type="submit">Create supplier account</button></form><p class="subtle-note">Already part of a supplier team? Ask your administrator to add your membership, then refresh.</p><button class="btn small" data-action="reload-membership">Refresh membership</button></div></main>`;}
function renderSupplier(){document.title=`${state.session||state.demo?supplierPages[state.page]?.[0]||'Overview':'Sign in'} · Gateway Supplier`;if(!state.session&&!state.demo){app.innerHTML=landing();return;}if(!state.supplierAccount){app.innerHTML=state.loading?'<main class="boot"><span class="brand-mark">g.</span><p>Loading your supplier memberships…</p></main>':supplierOnboarding();return;}const p=supplierPages;app.innerHTML=`<div class="layout supplier-layout"><aside class="sidebar" id="sidebar">${brand()}<div><div class="eyebrow" style="padding:0 14px 12px">SUPPLIER PORTAL</div><nav class="nav" aria-label="Supplier navigation">${Object.entries(p).map(([key,[name,ico]])=>`<a href="#/${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}>${icon(ico)}${name}</a>`).join('')}</nav></div><div class="sidebar-bottom"><div class="sidebar-note">${icon('truck')}<h3>Stay connected.</h3><p>Clear orders and delivery confirmations keep everyone in sync.</p></div><div class="side-user"><span class="avatar">S</span><div class="user-info"><strong>${e(state.supplierAccount.name)}</strong><small>${state.demo?'Read-only sample':'Supplier account'}</small></div><button class="btn ghost small" data-action="${state.demo?'exit-demo':'logout'}" aria-label="${state.demo?'Exit sample workspace':'Sign out'}">${icon('logout')}</button></div></div></aside><div><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><strong>${p[state.page][0]}</strong></div><div class="topbar-right"><button class="btn small" data-action="switch-portal">Switch portal</button><select id="supplier-account-picker" class="workspace-select" aria-label="Choose supplier account">${state.supplierAccounts.map(a=>`<option value="${e(a.id)}" ${a.id===state.supplierAccount.id?'selected':''}>${e(a.name)}</option>`).join('')}</select><button class="icon-button" data-action="refresh" aria-label="Refresh supplier data" ${state.loading?'disabled':''}>${icon('refresh')}</button></div></header><main class="content" id="main">${state.demo?'<div class="demo-banner"><p><strong>Supplier sample</strong> · Fictional orders and restaurant connections.</p><button class="btn small" data-action="exit-demo">Sign in</button></div>':''}${state.error?`<div class="error-banner" role="alert">${e(state.error)}</div>`:''}${state.loading?empty('Loading your supplier workspace…','Getting your approved connections and orders.'):supplierContent(state)}<p class="subtle-note">${state.demo?'Fictional sample data':state.updated?'Last refreshed '+date(state.updated,true):''} · Delivery confirmations are recorded by restaurants.</p></main></div></div>`;}
async function connectionForm(id){if(!canManage())return;const rid=state.restaurant.id;const {data,error}=await db.from('restaurant_supplier_connections').select('id,supplier_account_id,status').eq('restaurant_id',rid).eq('supplier_id',id).maybeSingle();if(rid!==state.restaurant?.id||state.portal!=='owner')return;if(error){toast(supplierError(error),true);return;}const details=data?`<p class="subtle-note">Current connection: ${e(label(data.status))}<br>Account code: ${e(data.supplier_account_id)}</p>${['accepted','pending'].includes(data.status)?`<button type="button" class="btn danger small" data-action="owner-revoke" data-id="${e(data.id)}">Disconnect supplier account</button>`:''}`:'';formDialog('connection','Connect supplier account',supplier(id)?.name||'Supplier',`${details}${field('Supplier connection code','supplier_account_id',data?.supplier_account_id||'','text','required maxlength="36"','Ask the supplier for the code shown in their Workspace page.')}<p class="subtle-note">After the supplier accepts, their account members can see this restaurant’s existing and future orders placed with this supplier, including product names, prices, and delivery receipts. They cannot see stock levels, usage, waste, or other suppliers. You can disconnect access here.</p>`,{supplierId:id},false,'Request connection');}
